import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlFormLabelComponent, VlFormMessageComponent, VlInputFieldComponent } from '@domg-wc/components/form';

// De validator zet de ValidityState-sleutel customError; de vl-form-message met state="customError" toont de fout.
// Een lege waarde is geldig: daarvoor zorgt required, met valueMissing.
const fooValidator = {
    key: 'customError',
    message: `Value does not equal 'foo'`,
    isValid(_instance, value) {
        if (!value) {
            return true;
        }
        return value === 'foo';
    },
};

// De validators staan in een statische array: een eigen component per validator, zodat niet elke vl-input-field
// hem krijgt. Het nieuwe element kent dezelfde attributen als vl-input-field.
class VlInputFieldWithFooValidatorComponent extends VlInputFieldComponent {
    static formControlValidators = [...VlInputFieldComponent.formControlValidators, fooValidator];
}
customElements.define('vl-input-field-with-foo-validator', VlInputFieldWithFooValidatorComponent);

registerWebComponents([VlFormLabelComponent, VlFormMessageComponent, VlButtonComponent]);

const form = document.querySelector('#form');
const field = document.querySelector('#waarde');

// Success-stijl na een geldige submit; weg bij een ongeldige submit of een reset.
form.addEventListener('submit', (event) => {
    event.preventDefault();
    field.setAttribute('success', '');
});
field.addEventListener('invalid', () => field.removeAttribute('success'));
form.addEventListener('reset', () => field.removeAttribute('success'));
